import {readFile} from 'node:fs/promises';import {decodeWire} from 'galbox-sdk/wire';import {expect} from '@playwright/test';import type {Page} from '@playwright/test';import {presentation} from './helpers.js';
/** These backups are generated by the complete real Core route, never hand-edited. */
export async function sourceCut(page:Page,locale:string,name:string){const backup:unknown=decodeWire('PortableBackup',new Uint8Array(await readFile(`artifacts/door2/cuts/${locale}-${name}.pb`)));await page.goto(`/?lang=${locale}&__test`);await presentation(page,'title');await page.locator('.game').click({position:{x:1,y:1}});return page.evaluate(async backup=>{const p=window.__fataTest?.player();if(!p)throw new Error('Player');const plan=p.prepareBackupRestore(backup),receipt=await p.commitBackupRestore(plan),slot=receipt.slots[0]?.restoredSlot;if(!slot)throw new Error('Source cut missing');await p.load(slot);return slot;},backup);}
export async function durableHead(page:Page){return page.evaluate(async()=>{const namespace=window.__fataTest?.player()?.getSnapshot().namespace;if(!namespace)throw new Error('Namespace');return new Promise<string>((resolve,reject)=>{const request=indexedDB.open('galbox-sdk',2);request.onerror=()=>reject(request.error);request.onsuccess=()=>{const db=request.result,r=db.transaction('namespaces','readonly').objectStore('namespaces').get(namespace);r.onerror=()=>{db.close();reject(r.error);};r.onsuccess=()=>{const value:unknown=r.result;if(!value||typeof value!=='object'||!('head'in value)){db.close();reject(new Error('Missing head'));return;}resolve(JSON.stringify(value.head));db.close();};};});});}
export async function idle(page:Page){await expect.poll(async()=>{await page.clock.runFor(16);return page.evaluate(()=>{const v=window.__fataTest?.player()?.getSnapshot();if(v?.error)throw new Error(v.error);return v?.lifecycle==='playing'&&v.loading.phase==='idle';});},{timeout:30000,intervals:[100]}).toBe(true);}
